mapper.select:
select 
from oa_sign_notification_outbox
where channel = #{channel}
  and recipient_user_id = #{recipientUserId}
  and business_key = #{businessKey}
limit 1

mapper.update:
update oa_sign_notification_outbox o
inner join oa_sign_task t
        on t.task_id = cast(json_unquote(json_extract(o.payload_json, '$.taskId')) as unsigned)
set o.status = 'SENDING',
    o.version = o.version + 1,
    o.updated_time = sysdate()
where o.outbox_id = #{outboxId}
  and o.status = #{expectedStatus}
  and o.version = #{version}

mapper.select:
select from oa_sign_notification_outbox o inner join oa_sign_task t on t.task_id = cast(json_unquote(json_extract(o.payload_json, '$.taskId')) as unsigned) where o.status = 'DEAD'
and t.shop_dept_id in
#{deptId}
and 1 = 0
order by o.updated_time desc, o.outbox_id desc limit #{limit}

select t.task_id as task_id, o.business_key as notification_business_key from oa_sign_task t inner join ( select cast(json_unquote(json_extract(dead.payload_json, '$.taskId')) as unsigned) as task_id, min(dead.outbox_id) as outbox_id from oa_sign_notification_outbox dead inner join oa_sign_task current_task on current_task.task_id = cast(json_unquote( json_extract(dead.payload_json, '$.taskId')) as unsigned) where dead.status = 'DEAD' and ( (json_unquote(json_extract(dead.payload_json, '$.routeType')) = 'OA_SIGN_HR_TASK' and dead.recipient_user_id = current_task.assigned_hr_user_id) or (json_unquote(json_extract(dead.payload_json, '$.routeType')) = 'OA_SIGN_PACKAGE_SIGN' and dead.recipient_user_id = current_task.employee_id) ) group by cast(json_unquote(json_extract(dead.payload_json, '$.taskId')) as unsigned) ) oldest_dead on oldest_dead.task_id = t.task_id inner join oa_sign_notification_outbox o on o.outbox_id = oldest_dead.outbox_id where 1 = 1 and t.assigned_hr_user_id = #{hrUserId}
and t.shop_dept_id in
#{deptId}
and 1 = 0
order by coalesce(o.updated_time, o.created_time), t.task_id limit #{limit}

select 
from oa_sign_notification_outbox o
inner join oa_sign_task t
        on t.task_id = cast(json_unquote(json_extract(o.payload_json, '$.taskId')) as unsigned)
       and t.task_id = #{taskId}
where o.business_key = #{businessKey}
  and t.assigned_hr_user_id = #{hrUserId}

order by o.outbox_id
